"""
Comprehensive test for MySQL AUTO_INCREMENT to T-SQL transpilation fix.
"""

import sqlglot

def test_comprehensive_scenarios():
    """Test various AUTO_INCREMENT scenarios"""

    test_cases = [
        # Basic case
        {
            "name": "Basic AUTO_INCREMENT",
            "sql": "create table tbl (id int auto_increment primary key, name varchar(20))",
            "should_contain": "IDENTITY(1, 1)",
            "should_not_contain": "AUTO_INCREMENT"
        },

        # Multiple columns with AUTO_INCREMENT (though this is unusual)
        {
            "name": "Table with other constraints",
            "sql": "create table tbl (id int auto_increment primary key, name varchar(20) not null, age int default 0)",
            "should_contain": "IDENTITY(1, 1)",
            "should_not_contain": "AUTO_INCREMENT"
        },

        # Different integer types
        {
            "name": "BIGINT AUTO_INCREMENT",
            "sql": "create table tbl (id bigint auto_increment primary key, data text)",
            "should_contain": "IDENTITY(1, 1)",
            "should_not_contain": "AUTO_INCREMENT"
        },

        # AUTO_INCREMENT without primary key
        {
            "name": "AUTO_INCREMENT without primary key",
            "sql": "create table tbl (id int auto_increment, name varchar(20), unique(id))",
            "should_contain": "IDENTITY(1, 1)",
            "should_not_contain": "AUTO_INCREMENT"
        },

        # Table without AUTO_INCREMENT (should not be affected)
        {
            "name": "Table without AUTO_INCREMENT",
            "sql": "create table tbl (id int primary key, name varchar(20))",
            "should_contain": "PRIMARY KEY",
            "should_not_contain": "IDENTITY"
        }
    ]

    print("=== Comprehensive AUTO_INCREMENT Tests ===")
    all_passed = True

    for i, test_case in enumerate(test_cases, 1):
        print(f"\nTest {i}: {test_case['name']}")
        print(f"  SQL: {test_case['sql']}")

        try:
            result = sqlglot.transpile(test_case['sql'], read='mysql', write='tsql', pretty=False)[0]
            print(f"  Result: {result}")

            # Check positive conditions
            if 'should_contain' in test_case:
                for expected in test_case['should_contain'].split(','):
                    expected = expected.strip()
                    if expected and expected not in result:
                        print(f"  ❌ FAIL: Expected '{expected}' not found in result")
                        all_passed = False

            # Check negative conditions
            if 'should_not_contain' in test_case:
                for unexpected in test_case['should_not_contain'].split(','):
                    unexpected = unexpected.strip()
                    if unexpected and unexpected in result:
                        print(f"  ❌ FAIL: Unexpected '{unexpected}' found in result")
                        all_passed = False

            if 'should_contain' in test_case or 'should_not_contain' in test_case:
                print(f"  ✅ PASS")

        except Exception as e:
            print(f"  ❌ ERROR: {e}")
            all_passed = False

    return all_passed

def test_backwards_compatibility():
    """Ensure we didn't break existing functionality"""
    print("\n=== Backwards Compatibility Tests ===")

    # Test that regular T-SQL generation still works
    tsql_statements = [
        "SELECT * FROM users WHERE id = 1",
        "INSERT INTO users (name, email) VALUES ('John', 'john@example.com')",
        "UPDATE users SET name = 'Jane' WHERE id = 1"
    ]

    all_passed = True
    for i, stmt in enumerate(tsql_statements, 1):
        print(f"\nCompat Test {i}: {stmt}")
        try:
            result = sqlglot.transpile(stmt, read='tsql', write='tsql', pretty=False)[0]
            print(f"  Result: {result}")
            print(f"  ✅ PASS")
        except Exception as e:
            print(f"  ❌ ERROR: {e}")
            all_passed = False

    return all_passed

if __name__ == "__main__":
