#!/usr/bin/env python3

"""
Test edge cases for CREATE TABLE CLONE and ALTER TABLE SWAP
"""

from sqllineage.runner import LineageRunner

def test_statement(sql, expected_sources=None, expected_targets=None):
    print(f"\nTesting: {sql}")
    try:
        runner = LineageRunner(sql)

        sources = {str(table) for table in runner.source_tables}
        targets = {str(table) for table in runner.target_tables}

        print(f"Sources: {sources}")
        print(f"Targets: {targets}")

        success = True
        if expected_sources is not None:
            # Convert expected sources to match actual format
            formatted_expected = set()
            for table in expected_sources:
                if '.' in table and not table.startswith('<default>.'):
                    formatted_expected.add(table)  # Fully qualified names
                else:
                    formatted_expected.add(f"<default>.{table.lower()}")  # Default schema + lowercase
            expected_sources = formatted_expected

            if sources != expected_sources:
                print(f"❌ MISMATCH - Expected sources: {expected_sources}")
                success = False
            else:
                print("✅ Sources match")

        if expected_targets is not None:
            # Convert expected targets to match actual format
            formatted_expected = set()
            for table in expected_targets:
                if '.' in table and not table.startswith('<default>.'):
                    formatted_expected.add(table)  # Fully qualified names
                else:
                    formatted_expected.add(f"<default>.{table.lower()}")  # Default schema + lowercase
            expected_targets = formatted_expected

            if targets != expected_targets:
                print(f"❌ MISMATCH - Expected targets: {expected_targets}")
                success = False
            else:
                print("✅ Targets match")

        if success:
            print("✅ TEST PASSED")
        else:
            print("❌ TEST FAILED")
        return success
    except Exception as e:
        print(f"❌ ERROR: {e}")
        return False

def main():
    print("=" * 60)
    print("TESTING EDGE CASES")
    print("=" * 60)

    all_passed = True

    # Basic cases
    all_passed &= test_statement("create table tab2 clone tab1", {"tab1"}, {"tab2"})
    all_passed &= test_statement("alter table tab1 swap with tab2", {"tab1", "tab2"}, {"tab1", "tab2"})

    # Cases with schema qualifiers
    all_passed &= test_statement("create table db1.tab2 clone db2.tab1", {"db2.tab1"}, {"db1.tab2"})
    all_passed &= test_statement("alter table db1.tab1 swap with db2.tab2", {"db1.tab1", "db2.tab2"}, {"db1.tab1", "db2.tab2"})

    # Mixed case (parser normalizes to lowercase)
    all_passed &= test_statement("CREATE TABLE TAB2 CLONE TAB1", {"tab1"}, {"tab2"})
    all_passed &= test_statement("ALTER TABLE TAB1 SWAP WITH TAB2", {"tab1", "tab2"}, {"tab1", "tab2"})

    # Extra whitespace
    all_passed &= test_statement("create  table  tab2  clone  tab1", {"tab1"}, {"tab2"})
    all_passed &= test_statement("alter  table  tab1  swap  with  tab2", {"tab1", "tab2"}, {"tab1", "tab2"})

    print(f"\n{'='*60}")
    if all_passed:
        print("🎉 ALL EDGE CASE TESTS PASSED!")
    else:
        print("❌ SOME TESTS FAILED")
    print(f"{'='*60}")

if __name__ == "__main__":
    main()

